  insert into public.ac_exams
    (title, subject, exam_code_hash, duration_minutes, positive_marks, negative_marks, pass_percentage, is_published, created_at)
  values
    (old_exam.title, old_exam.subject, old_exam.exam_code_hash, old_exam.duration_minutes,
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'The Living World', 'A herbarium label records a plant as Mangifera indica L. In this name, ‘L.’ denotes:', '["The family name", "The author who validly published the name", "The locality of collection", "The order of the plant"]'::jsonb, 1, '‘L.’ is the standard abbreviation for Linnaeus, the author associated with the scientific name.', 1);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'The Living World', 'Which pair represents the correct taxonomic order from lower to higher category?', '["Family → Genus → Order", "Species → Genus → Family", "Class → Order → Phylum", "Genus → Species → Family"]'::jsonb, 1, 'The hierarchy proceeds species, genus, family, order, class, phylum/division and kingdom.', 2);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Biological Classification', 'A prokaryote survives in highly saline water and has ether-linked membrane lipids. It most likely belongs to:', '["Eubacteria", "Archaea", "Fungi", "Protozoa"]'::jsonb, 1, 'Many archaea have distinctive ether-linked membrane lipids and include extremophiles.', 3);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Biological Classification', 'In the five-kingdom system, organisms with absorptive heterotrophic nutrition and chitinous cell walls are placed in:', '["Monera", "Protista", "Fungi", "Plantae"]'::jsonb, 2, 'Fungi absorb nutrients and typically have chitin in their cell walls.', 4);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Plant Kingdom', 'Which feature distinguishes heterosporous pteridophytes from homosporous forms?', '["They produce seeds", "They produce microspores and megaspores", "They lack vascular tissue", "Their gametophyte is always absent"]'::jsonb, 1, 'Heterospory produces two spore types that develop into male and female gametophytes.', 5);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Plant Kingdom', 'In a typical fern, meiosis that produces haploid spores occurs in the:', '["Antheridium", "Archegonium", "Sporangium", "Protonema"]'::jsonb, 2, 'Diploid spore mother cells in sporangia undergo meiosis to form haploid spores.', 6);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Morphology of Flowering Plants', 'A flower has a superior ovary and other floral whorls arise below it. The flower is:', '["Epigynous", "Perigynous", "Hypogynous", "Actinomorphic"]'::jsonb, 2, 'In a hypogynous flower, the ovary is superior and other whorls arise below it.', 7);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Morphology of Flowering Plants', 'The swollen base of a leaf that partly or wholly encloses the stem is called:', '["Pulvinus", "Leaf sheath", "Petiole", "Stipule"]'::jsonb, 1, 'A leaf sheath is common in grasses and wraps around the stem.', 8);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Cell: The Unit of Life', 'A cell contains 70S ribosomes in an organelle with its own circular DNA. The organelle is most likely:', '["Golgi apparatus", "Lysosome", "Mitochondrion", "Smooth ER"]'::jsonb, 2, 'Mitochondria contain circular DNA and prokaryote-like 70S ribosomes.', 9);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Cell: The Unit of Life', 'Which transport process can move a substance against its concentration gradient using ATP?', '["Simple diffusion", "Osmosis", "Active transport", "Facilitated diffusion"]'::jsonb, 2, 'Active transport uses energy to move substances against their electrochemical gradient.', 10);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Cell Cycle and Cell Division', 'A diploid cell has 2n = 12 chromosomes. At metaphase of mitosis, it contains:', '["6 chromosomes and 12 chromatids", "12 chromosomes and 24 chromatids", "24 chromosomes and 24 chromatids", "12 chromosomes and 12 chromatids"]'::jsonb, 1, 'Each of the 12 replicated chromosomes consists of two sister chromatids.', 11);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Cell Cycle and Cell Division', 'Failure of homologous chromosomes to separate during meiosis I is called:', '["Crossing over", "Nondisjunction", "Cytokinesis", "Synapsis"]'::jsonb, 1, 'Nondisjunction produces gametes with abnormal chromosome numbers.', 12);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Structural Organisation in Animals', 'Which connective tissue cell primarily secretes histamine during allergic responses?', '["Fibroblast", "Mast cell", "Chondrocyte", "Osteocyte"]'::jsonb, 1, 'Mast cells release histamine and other mediators during inflammatory and allergic responses.', 13);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Structural Organisation in Animals', 'The epithelium lining most of the small intestine is adapted for absorption and is primarily:', '["Simple columnar", "Stratified squamous", "Simple cuboidal", "Transitional"]'::jsonb, 0, 'Simple columnar epithelium with microvilli increases absorptive surface area.', 14);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Body Fluids and Circulation', 'If the SA node fails, which structure can usually initiate a slower intrinsic cardiac rhythm?', '["AV node", "Aortic valve", "Papillary muscle", "Coronary artery"]'::jsonb, 0, 'The AV node can act as a secondary pacemaker, typically at a slower rate.', 15);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Body Fluids and Circulation', 'A person with blood group AB (Rh positive) can generally receive packed red cells from which ABO/Rh group in a standard compatibility model?', '["O negative only", "AB positive only", "All ABO/Rh groups, after compatibility testing", "A negative and B negative only"]'::jsonb, 2, 'AB positive recipients are considered universal red-cell recipients in the simplified ABO/Rh model, but crossmatching is still required.', 16);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Body Fluids and Circulation', 'The first heart sound (S1) is produced mainly by closure of the:', '["Aortic and pulmonary valves", "Mitral and tricuspid valves", "Coronary ostia", "Venae cavae"]'::jsonb, 1, 'S1 occurs at the beginning of ventricular systole as the atrioventricular valves close.', 17);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Breathing and Respiration', 'Most oxygen in human blood is transported:', '["Dissolved in plasma", "Bound reversibly to haemoglobin", "As bicarbonate ions", "Bound to albumin"]'::jsonb, 1, 'The majority of oxygen binds reversibly to haemoglobin in red blood cells.', 18);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Breathing and Respiration', 'A rightward shift of the oxyhaemoglobin dissociation curve is promoted by:', '["Lower CO₂ and higher pH", "Lower temperature", "Higher CO₂ and lower pH", "Reduced 2,3-BPG"]'::jsonb, 2, 'Higher CO₂ and H⁺ reduce haemoglobin’s oxygen affinity, facilitating tissue unloading.', 19);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Excretory Products and their Elimination', 'Glucose appears in urine when filtered glucose exceeds the renal threshold mainly because:', '["The glomerulus stops filtering", "Tubular reabsorption carriers become saturated", "ADH secretion stops completely", "The loop of Henle secretes glucose"]'::jsonb, 1, 'When transport maximum is exceeded, proximal tubular glucose reabsorption cannot keep up with filtration.', 20);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Excretory Products and their Elimination', 'Which nephron segment is normally impermeable to water while actively reabsorbing NaCl?', '["Descending limb of loop of Henle", "Ascending limb of loop of Henle", "Collecting duct in the presence of ADH", "Proximal convoluted tubule"]'::jsonb, 1, 'The ascending limb reabsorbs salts but is largely impermeable to water.', 21);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Locomotion and Movement', 'During skeletal muscle contraction, the length of which structure remains essentially unchanged?', '["I band", "H zone", "A band", "Distance between Z lines"]'::jsonb, 2, 'The A band corresponds to thick filament length and remains constant during sliding-filament contraction.', 22);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Locomotion and Movement', 'At the neuromuscular junction, acetylcholine normally initiates muscle action potential by opening:', '["Ligand-gated cation channels", "Voltage-gated chloride channels only", "ATP-sensitive potassium channels", "Aquaporins"]'::jsonb, 0, 'Acetylcholine binds nicotinic receptors, opening cation channels and depolarising the motor end plate.', 23);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'The Living World', 'A taxonomic key identifies organisms using paired contrasting statements. Each pair is a:', '["Couplet", "Taxon", "Holotype", "Flora"]'::jsonb, 0, 'A couplet contains two contrasting leads used to proceed through a dichotomous key.', 24);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Biological Classification', 'Viruses are described as obligate intracellular parasites because they:', '["Have no genetic material", "Replicate only inside living host cells", "Always possess both DNA and RNA", "Perform independent protein synthesis"]'::jsonb, 1, 'Viruses depend on host-cell machinery for replication and protein production.', 25);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Plant Kingdom', 'The dominant, conspicuous plant body in mosses is the:', '["Sporophyte", "Gametophyte", "Zygote", "Embryo"]'::jsonb, 1, 'The moss gametophyte is the main photosynthetic generation; the sporophyte remains attached.', 26);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Morphology of Flowering Plants', 'In a diadelphous androecium, stamens are united into:', '["One bundle", "Two bundles", "Three bundles", "A completely fused anther"]'::jsonb, 1, 'Diadelphous stamens form two bundles, as in many legumes.', 27);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Cell: The Unit of Life', 'A protein destined for secretion is most likely synthesised by ribosomes attached to:', '["Rough endoplasmic reticulum", "Smooth endoplasmic reticulum", "Peroxisomes", "Centrioles"]'::jsonb, 0, 'Secretory proteins enter the rough ER during synthesis and move through the Golgi pathway.', 28);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Cell Cycle and Cell Division', 'The synaptonemal complex is associated with which meiotic event?', '["Separation of sister chromatids", "Pairing of homologous chromosomes", "Cytokinesis in telophase II", "DNA replication in S phase"]'::jsonb, 1, 'The synaptonemal complex helps homologous chromosomes pair during prophase I.', 29);
  insert into public.ac_exam_questions (exam_id, chapter, question_text, options, correct_option, explanation, sort_order) values (target_exam, 'Structural Organisation in Animals', 'Which component of blood is chiefly responsible for antibody production after differentiation?', '["Erythrocyte", "Plasma cell", "Platelet", "Neutrophil"]'::jsonb, 1, 'Activated B lymphocytes can differentiate into plasma cells that secrete antibodies.', 30);
